    return `${accent('/')} ${typingFilter ? reportFilter.render(inner - 2)[0] : clean(query)}`;
  };
  const reportTabRows = (inner, y) => {
    const tabs = reportKinds.map(kind => {
      const matches = reportsOfKind(kind.name).length;
