          const listKey = key(data, 'up') || key(data, 'down') || key(data, 'enter');
          const target = onOtherRow() && !listKey ? question.other : question.selection;
          target.handleInput(data);
        }
        changed();
        return;
      }
      if (choosing) {
        handleChoosingKey(data);
        changed();
        return;
      }
