        view = 'conversation';
        focus = 'composer';
        scroll = 0;
      } else if (typingFilter && (reportFilter.getValue() || !(key(data, 'left') || key(data, 'right')))) {
        handleFilterKey(data);
      } else if ((key(data, 'left') || key(data, 'right'))
        && (focus !== 'composer' || !editor.getExpandedText())) {
        const tabs = views();
